R is made for statistics. Surprisingly, though, there is no built-in R function to find the statistical mode: the most frequent value in a given distribution. (The base R function mode() has a very different use case.)
Here are three mode functions for you.
All functions behave the same way if there is only one mode. If there are multiple modes, mode_first() only returns the one that appears first. mode_all() returns all modes. mode_single() returns NA in this case.
mode_first &lt;- function(x, na.rm = FALSE, first_known = TRUE) {
  if (na.rm) {
    x &lt;- x[!is.na(x)]
  }
  ux &lt;- unique(x[!is.na(x)])
  tab &lt;- tabulate(match(x, ux))
  mode1 &lt;- ux[which.max(tab)]
  if (!any(is.na(x))) {
    return(mode1)
  }
  count_mode2_na &lt;- sort(tab, decreasing = TRUE)[-1L]
  if (!length(count_mode2_na)) {
    count_mode2_na &lt;- 0L
  }
  count_mode2_na &lt;- max(count_mode2_na) + length(x[is.na(x)])
  if (first_known) {
    count_mode2_na &lt;- count_mode2_na - 1
  }
  if (max(tab) &gt; count_mode2_na) {
    return(mode1)
  }
  mode2 &lt;- ux[which.max(tabulate(match(x[x != mode1], ux)))]
  mode1_appears_first &lt;- match(mode1, x) &lt; match(mode2, x)
  mode1_is_half_or_more &lt;- max(tab) &gt;= length(x) / 2
  if (mode1_is_half_or_more && (mode1_appears_first || first_known)) {
    mode1
  } else if (is.na(decide_mode_na(x, ux, mode1))) {
    methods::as(NA, typeof(x))
  } else if (length(ux) == 1L && mode1_is_half_or_more) {
    mode1
  } else {
    methods::as(NA, typeof(x))
  }
}

mode_all &lt;- function(x, na.rm = FALSE) {
  if (na.rm) {
    x &lt;- x[!is.na(x)]
  }
  ux &lt;- unique(x[!is.na(x)])
  tab &lt;- tabulate(match(x, ux))
  modes &lt;- ux[tab == max(tab)]
  if (length(modes) == 1L) {
    decide_mode_na(x, ux, modes)
  } else if (any(is.na(x))) {
    methods::as(NA, typeof(x))
  } else {
    modes
  }
}

mode_single &lt;- function(x, na.rm = FALSE) {
  if (na.rm) {
    x &lt;- x[!is.na(x)]
  }
  mode1 &lt;- mode_all(x, FALSE)
  if (length(mode1) == 1L) {
    decide_mode_na(x, unique(x[!is.na(x)]), mode1)
  } else {
    methods::as(NA, typeof(x))
  }
}

# Helper used in all functions above; don't call directly:
decide_mode_na &lt;- function(x, ux, mode1) {
  if (length(ux) == 1L) {
    if (length(x[is.na(x)]) &lt; length(x) / 2) {
      return(mode1)
    } else {
      return(methods::as(NA, typeof(x)))
    }
  }
  mode2 &lt;- ux[which.max(tabulate(match(x[x != mode1], ux)))]
  count_mode1 &lt;- length(x[x == mode1])
  count_mode2_na &lt;- length(x[x == mode2]) + length(x[is.na(x)])
  if (count_mode1 &gt; count_mode2_na) {
    mode1
  } else {
    methods::as(NA, typeof(x))
  }
}
At their core, these functions are based on a Stack Overflow answer by Ken Williams. Go to Implementation notes below for details.
What is so special about these functions? They really care about NAs. Let’s have a look.

This is helpful in the following situation: You are writing a function that wraps a tidyselect-using function, like dplyr::across(), and passes a tidyselect specification on to it. By default, however, your new function should select a set of columns that is different from the set of columns that the wrapped function would select by default.
You don’t like the existing default, so you need to write a new one yourself.
library(dplyr) |&gt; 
  suppressPackageStartupMessages()

# For better printing:
iris &lt;- iris |&gt; 
  as_tibble() |&gt; 
  slice(1:3)
You may already know that you can “tunnel” an argument into across() with { }:
by_1000 &lt;- function(data, selector) {
  dplyr::mutate(data, dplyr::across(
    .cols = {{ selector }},
    .fns  = \(x) x * 1000
  ))
}

iris |&gt; 
  by_1000(1:2)

# A tibble: 3 × 5
  Sepal.Length Sepal.Width Petal.Length Petal.Width Species
         &lt;dbl&gt;       &lt;dbl&gt;        &lt;dbl&gt;       &lt;dbl&gt; &lt;fct&gt;  
1         5100        3500          1.4         0.2 setosa 
2         4900        3000          1.4         0.2 setosa 
3         4700        3200          1.3         0.2 setosa
This works fine so far, but there is a catch. If the user doesn’t specify the selector argument, by_1000() won’t operate on any columns but simply return the tibble as is:
iris |&gt; 
  by_1000()

# A tibble: 3 × 5
  Sepal.Length Sepal.Width Petal.Length Petal.Width Species
         &lt;dbl&gt;       &lt;dbl&gt;        &lt;dbl&gt;       &lt;dbl&gt; &lt;fct&gt;  
1          5.1         3.5          1.4         0.2 setosa 
2          4.9         3            1.4         0.2 setosa 
3          4.7         3.2          1.3         0.2 setosa
Perhaps this is not the default you want. The function you apply, multiply by 1000, is an arithmetic operation. It might be best to select all numeric columns by default!
How to do this? You need to check whether or not the user actually specified the selector argument. If not, reassign a custom default expression to selector using rlang::expr(). It should only be evaluated within across(), where this requires the injection operator, !!, instead of { }:
# THIS MAKES MUCH MORE SENSE NOW THAT `where(is.numeric)` IS A LITERAL, IMMEDIATE ARGUMENT DEFAULT; AND THIS NEGATES THE WHOLE PURPOSE OF THIS BLOGPOST! THE OTHER ONE, ABOUT NEUTRAL ELEMENTS, STILL MAKES SENSE, THOUGH. MAYBE INTEGRATE INE INTRODUCTORY STAPS FROM HERE INTO THERE, AND TURN IT INTO ONE COMPREHENSIVE BLOGPOST ABOUT PROGRAMMING WITH `across()`?
multiply_df &lt;- function(data, cols = where(is.numeric), by = 1000) {
  # if (is.null(cols)) {
  #   cols &lt;- rlang::expr(where(is.numeric))
  # }
  dplyr::mutate(data, dplyr::across(
    .cols = {{ cols }},
    .fns  = \(x) x * by
  ))
}

iris |&gt; 
  multiply_df()

# A tibble: 3 × 5
  Sepal.Length Sepal.Width Petal.Length Petal.Width Species
         &lt;dbl&gt;       &lt;dbl&gt;        &lt;dbl&gt;       &lt;dbl&gt; &lt;fct&gt;  
1         5100        3500         1400         200 setosa 
2         4900        3000         1400         200 setosa 
3         4700        3200         1300         200 setosa

library(dplyr) |&gt; 
  suppressPackageStartupMessages()

iris &lt;- iris |&gt; 
  as_tibble() |&gt; 
  slice(1:3)

mult_1000 &lt;- function(data, cols = everything(), check_numeric = TRUE) {
  if (check_numeric) {
    selection2 &lt;- rlang::expr(where(is.numeric))
  } else {
    selection2 &lt;- rlang::expr(everything())
  }
  dplyr::mutate(data, dplyr::across(
    .cols = {{ cols }} & !!selection2,
    .fns  = function(x) x * 1000
  ))
}

mult_1000(iris)

# A tibble: 3 × 5
  Sepal.Length Sepal.Width Petal.Length Petal.Width Species
         &lt;dbl&gt;       &lt;dbl&gt;        &lt;dbl&gt;       &lt;dbl&gt; &lt;fct&gt;  
1         5100        3500         1400         200 setosa 
2         4900        3000         1400         200 setosa 
3         4700        3200         1300         200 setosa
